 private static Map<String,Object> nullableMap(Object...pairs){var v=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)v.put((String)pairs[i],pairs[i+1]);return v;}
 private void insert(String table,Map<String,Object> v){var cols=new ArrayList<>(v.keySet());one(db.update("INSERT INTO "+table+"("+String.join(",",cols)+") VALUES("+String.join(",",Collections.nCopies(cols.size(),"?"))+")",cols.stream().map(v::get).toArray()));}
